import{_ as n,a0 as d,w as p,s as o,I as i,x as s,a1 as t,A as l,ao as h}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何使用 Buildah 构建容器镜像 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 Buildah 构建容器镜像 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 Buildah 构建容器镜像 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 Buildah 构建容器镜像 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180503 How to build container images with Buildah","title":"如何使用 Buildah 构建容器镜像","tag":"201805","desc":""},"relativePath":"201805/20180503 How to build container images with Buildah.md","filePath":"[post].md"}'),r={name:"201805/20180503 How to build container images with Buildah.md"};function g(u,a,b,k,c,f){const e=d("Link");return p(),o("div",null,[a[21]||(a[21]=i("h1",{id:"如何使用-buildah-构建容器镜像",tabindex:"-1"},[s("如何使用 Buildah 构建容器镜像 "),i("a",{class:"header-anchor",href:"#如何使用-buildah-构建容器镜像","aria-label":"Permalink to “如何使用 Buildah 构建容器镜像”"},"​")],-1)),a[22]||(a[22]=i("p",null,[i("img",{src:"https://fedoramagazine.org/wp-content/uploads/2018/04/buildah-816x345.png",alt:""})],-1)),i("p",null,[a[1]||(a[1]=s("Project Atomic 通过他们在 Open Container Initiative（OCI）上的努力创造了一个名为 ",-1)),t(e,{href:"https://github.com/projectatomic/buildah"},{default:l(()=>[...a[0]||(a[0]=[s("Buildah",-1)])]),_:1}),a[2]||(a[2]=s(" 的伟大工具。Buildah 能帮助创建、构建和更新，它支持 Docker 容器镜像以及 OCI 兼容镜像。",-1))]),a[23]||(a[23]=h(`<p>Buildah 处理构建容器镜像时无需安装完整的容器运行时或守护进程。这对建立容器的持续集成和持续交付管道尤其有用。</p><p>Buildah 使容器的文件系统可以直接供构建主机使用。这意味着构建工具在主机上可用就行，而不需要在容器镜像中可用，从而使构建更快速，镜像更小，更安全。Buildah 有 CentOS、Fedora 和 Debian 的软件包。</p><h3 id="安装-buildah" tabindex="-1">安装 Buildah <a class="header-anchor" href="#安装-buildah" aria-label="Permalink to “安装 Buildah”">​</a></h3><p>从 Fedora 26 开始 Buildah 可以使用 <code>dnf</code> 进行安装。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install buildah -y</span></span></code></pre></div><p><code>buildah</code> 的当前版本为 0.16，可以通过以下命令显示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ buildah --version</span></span></code></pre></div><h3 id="基本命令" tabindex="-1">基本命令 <a class="header-anchor" href="#基本命令" aria-label="Permalink to “基本命令”">​</a></h3><p>构建容器镜像的第一步是获取基础镜像，这是通过 Dockerfile 中的 <code>FROM</code> 语句完成的。Buildah 以类似的方式处理这个。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo buildah from fedora</span></span></code></pre></div><p>该命令将拉取 Fedora 的基础镜像并存储在主机上。通过执行以下操作可以检查主机上可用的镜像。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo buildah images</span></span>
<span class="line"><span>IMAGE ID IMAGE NAME CREATED AT SIZE</span></span>
<span class="line"><span>9110ae7f579f docker.io/library/fedora:latest Mar 7, 2018 20:51 234.7 MB</span></span></code></pre></div><p>在拉取基础镜像后，有一个该镜像的运行容器实例，这是一个“工作容器”。</p><p>以下命令显示正在运行的容器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo buildah containers</span></span>
<span class="line"><span>CONTAINER ID BUILDER IMAGE ID IMAGE NAME</span></span>
<span class="line"><span>CONTAINER NAME</span></span>
<span class="line"><span>6112db586ab9 * 9110ae7f579f docker.io/library/fedora:latest fedora-working-container</span></span></code></pre></div><p>Buildah 还提供了一个非常有用的命令来停止和删除当前正在运行的所有容器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo buildah rm --all</span></span></code></pre></div><p>完整的命令列表可以使用 <code>--help</code> 选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ buildah --help</span></span></code></pre></div><h3 id="构建一个-apache-web-服务器容器镜像" tabindex="-1">构建一个 Apache Web 服务器容器镜像 <a class="header-anchor" href="#构建一个-apache-web-服务器容器镜像" aria-label="Permalink to “构建一个 Apache Web 服务器容器镜像”">​</a></h3><p>让我们看看如何使用 Buildah 在 Fedora 基础镜像上安装 Apache Web 服务器，然后复制一个可供服务的自定义 <code>index.html</code>。</p><p>首先让我们创建自定义的 <code>index.html</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;Hello Fedora Magazine !!!&quot; &gt; index.html</span></span></code></pre></div><p>然后在正在运行的容器中安装 httpd 包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo buildah from fedora</span></span>
<span class="line"><span>$ sudo buildah run fedora-working-container dnf install httpd -y</span></span></code></pre></div><p>让我们将 <code>index.html</code> 复制到 <code>/var/www/html/</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo buildah copy fedora-working-container index.html /var/www/html/index.html</span></span></code></pre></div><p>然后配置容器入口点以启动 httpd。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo buildah config --entrypoint &quot;/usr/sbin/httpd -DFOREGROUND&quot; fedora-working-container</span></span></code></pre></div><p>现在为了使“工作容器”可用，<code>commit</code> 命令将容器保存到镜像。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo buildah commit fedora-working-container hello-fedora-magazine</span></span></code></pre></div><p>hello-fedora-magazine 镜像现在可用，并且可以推送到仓库以供使用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo buildah images</span></span>
<span class="line"><span>IMAGE ID IMAGE NAME CREATED</span></span>
<span class="line"><span>AT SIZE</span></span>
<span class="line"><span>9110ae7f579f docker.io/library/fedora:latest</span></span>
<span class="line"><span>Mar 7, 2018 22:51 234.7 MB</span></span>
<span class="line"><span>49bd5ec5be71 docker.io/library/hello-fedora-magazine:latest</span></span>
<span class="line"><span>Apr 27, 2018 11:01 427.7 MB</span></span></code></pre></div><p>通过运行以下步骤，还可以使用 Buildah 来测试此镜像。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo buildah from --name=hello-magazine docker.io/library/hello-fedora-magazine</span></span>
<span class="line"><span>$ sudo buildah run hello-magazine</span></span></code></pre></div>`,35)),i("p",null,[a[4]||(a[4]=s("访问 ",-1)),t(e,{href:"http://localhost"},{default:l(()=>[...a[3]||(a[3]=[s("http://localhost",-1)])]),_:1}),a[5]||(a[5]=s(" 将显示 “Hello Fedora Magazine !!!”",-1))]),a[24]||(a[24]=i("hr",null,null,-1)),i("p",null,[a[7]||(a[7]=s("via: ",-1)),t(e,{href:"https://fedoramagazine.org/daemon-less-container-management-buildah/"},{default:l(()=>[...a[6]||(a[6]=[s("https://fedoramagazine.org/daemon-less-container-management-buildah/",-1)])]),_:1})]),i("p",null,[a[12]||(a[12]=s("作者：",-1)),t(e,{href:"https://fedoramagazine.org/author/ashutoshbhakare/"},{default:l(()=>[...a[8]||(a[8]=[s("Ashutosh Sudhakar Bhakare",-1)])]),_:1}),a[13]||(a[13]=s(" 选题：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:l(()=>[...a[9]||(a[9]=[s("lujun9972",-1)])]),_:1}),a[14]||(a[14]=s(" 译者：",-1)),t(e,{href:"https://github.com/geekpi"},{default:l(()=>[...a[10]||(a[10]=[s("geekpi",-1)])]),_:1}),a[15]||(a[15]=s(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:l(()=>[...a[11]||(a[11]=[s("wxy",-1)])]),_:1})]),i("p",null,[a[18]||(a[18]=s("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...a[16]||(a[16]=[s("LCTT",-1)])]),_:1}),a[19]||(a[19]=s(" 原创编译，",-1)),t(e,{href:"https://linux.cn/"},{default:l(()=>[...a[17]||(a[17]=[s("Linux中国",-1)])]),_:1}),a[20]||(a[20]=s(" 荣誉推出",-1))])])}const x=n(r,[["render",g]]);export{C as __pageData,x as default};
